import { IconClose } from "@airbus/icons";
import { focus, svgColor, svgUri } from "../../helpers";
import { buttonReset } from "../Button";
import { StyleFn } from "..";

export const Chip: StyleFn = (theme, mode) => {
  const { color, font, size } = theme;
  const { focusWithPseudo } = focus(theme, mode);

  const getLabelStyles = (height: any, padding: any) => ({
    paddingLeft: padding,
    paddingRight: padding,
    lineHeight: height,
  });

  const getIconStyles = (height: any, padding: any, margin?: any) => ({
    fontSize: height,
    height,
    paddingLeft: padding,
    marginRight: margin ? `-${margin}` : `calc(${padding}/-2)`,
    "& svg": {
      fill: "currentColor",
      fontSize: height,
      width: height,
      height: height,
      display: "block",
    },
  });

  const getRemoveBtnStyles = (height: any) => ({
    width: `calc(${height} + 2px)`,
    height: `calc(${height} + 2px)`,
    backgroundSize: height,
  });

  // FIXME use lighter/darker color tokens based on feedback color tokens ?
  // warning color is based on orange for chip, instead of yellow for all other components...
  // @see https://chat.google.com/room/AAAA7SsHhrU/UFcFlaQU_mk
  const bgColors = {
    info: color.surface.feedback.information.default[mode],
    success: color.surface.feedback.success.default[mode],
    warning: color.surface.feedback.warning.default[mode],
    error: color.surface.feedback.error.default[mode],
  };
  const textColors = {
    info: color.text.neutral.minimal[mode],
    success: color.text.neutral.minimal[mode],
    warning: color.text.feedback.warning.onsurface[mode],
    error: color.text.neutral.minimal[mode],
    corporate: color.text.accent.corporate[mode]
  };

  return {
    root: {
      // layout
      display: "inline-flex",
      alignItems: "center",
      whiteSpace: "nowrap",
      justifyContent: "center",
      verticalAlign: "middle",
      // reset
      border: "none",
      cursor: "default",
      padding: 0,
      outline: 0,
      // look
      color: color.text.neutral.default[mode],
      backgroundColor: color.surface.componentonbackground.moderate[mode],
      fontSize: font.size.small,
      fontWeight: font.weight.medium,
      height: size.spacing[24],
      borderRadius: size.spacing[12],
      "&:has(button)":{
        color: textColors.corporate,
      },
    },
    label: {
      ...getLabelStyles(size.spacing[24], size.spacing[12]),
      overflow: "hidden",
      textOverflow: "ellipsis",
      whiteSpace: "nowrap",
    },
    removeBtn: {
      extend: [
        buttonReset,
        focusWithPseudo({ radius: "50%", offset: 5 }),
        getRemoveBtnStyles(size.spacing[16]),
      ],
      padding: size.spacing[2],
      margin: `0 ${size.spacing[4]} 0 -${size.spacing[4]}`,
      backgroundImage: svgUri(
        svgColor(
          IconClose.data,
          color.surface.componentonbackground.moderate[mode]
        )
      ),
      backgroundRepeat: "no-repeat",
      backgroundPosition: "left 50% top 50%",
      backgroundColor: color.surface.accent.default[mode],
      borderRadius: "50%",
      color: "",
      "&:hover": {
        backgroundColor: color.text.link.neutral.default[mode],
      },
      "&:active": {
        backgroundColor: color.surface.accent.active[mode],
      },
      "&$_warning": {
        "&:hover": {
          backgroundColor: color.text.feedback.warning.onsurface[mode],
        },
      }
    },
    icon: getIconStyles(size.spacing[16], size.spacing[12], size.spacing[4]),
    _active: {},
    _clickable: {
      extend: [focusWithPseudo({ radius: size.radius[1000], offset: 5 })],
      cursor: "pointer",
      userSelect: "none",
      WebkitTapHighlightColor: "transparent",
      color: textColors.corporate,
      "&$_success": {
        "&:hover": {
          color: textColors.corporate,
          backgroundColor: color.dimmed.green[mode],
        },
        "&:active": {
          color: textColors.success,
          backgroundColor: color.surface.feedback.success.active[mode],
        },
      },
      "&$_warning": {
        "&:hover": {
          color: textColors.warning,
          backgroundColor: color.dimmed.yellow[mode],
        },
        "&:active": {
          color: textColors.warning,
          backgroundColor: color.surface.feedback.warning.active[mode],
        },
      },
      "&$_error": {
        "&:hover": {
          color: color.text.neutral.default[mode],
          backgroundColor: color.dimmed.red[mode],
        },
        "&:active": {
          color: textColors.error,
          backgroundColor: color.surface.feedback.error.active[mode],
        },
      },
      "&$_info": {
        "&:hover": {
          color: textColors.corporate,
          backgroundColor: color.dimmed.blue[mode],
        },
        "&:active": {
          color: textColors.info,
          backgroundColor: color.surface.accent.default[mode],
        },
      },
      "&:hover": {
        backgroundColor: color.surface.componentonbackground.strong[mode],
      },
      "&:active": {
        color: textColors.info,
        backgroundColor: color.surface.accent.active[mode],
      },
      // applying pseudo active class manually, since browsers automatically
      // apply it on click only for buttons, a, and input elements
      "&$_active": {
        color: textColors.info,
        backgroundColor: color.surface.accent.active[mode],
      }
    },
    _info: {
      backgroundColor: bgColors.info,
      "&$_info&": { 
        color: textColors.info,
        "& $removeBtn": {
          backgroundColor: textColors.info,
          backgroundImage: svgUri(svgColor(IconClose.data, bgColors.info)),
          opacity: 1,
          "&:hover": {
            opacity: 0.65,
          },
          "&:active": {
            backgroundImage: svgUri(svgColor(IconClose.data, bgColors.info)),
            opacity: 0.85
          },
        },
      }
    },
    _success: {
      backgroundColor: bgColors.success,
      "&$_success&": { 
        color: textColors.success,
        "& $removeBtn": {
          backgroundColor: textColors.success,
          backgroundImage: svgUri(svgColor(IconClose.data, bgColors.success)),
          opacity: 1,
          "&:hover": {
            opacity: 0.70,
          },
          "&:active": {
            backgroundImage: svgUri(svgColor(IconClose.data, bgColors.success)),
            opacity: 0.85
          },
        },
      }
    },
    _warning: {
      backgroundColor: bgColors.warning,
      color: textColors.warning,
      // increased specificity. if value is same values in both modes, JSS merges them and
      // dark mode styles are not applied
      "&$_warning&": { 
        color: textColors.warning,
        "& $removeBtn": {
          backgroundColor: color.text.feedback.warning.onsurface[mode],
          backgroundImage: svgUri(svgColor(IconClose.data, bgColors.warning)),
          opacity: 1,
          "&:hover": {
            backgroundColor: color.text.feedback.warning.ondimmed[mode],
            backgroundImage: svgUri(svgColor(IconClose.data, bgColors.warning)),
          },
          "&:active": {
            backgroundColor: color.text.feedback.warning.onsurface[mode],
            backgroundImage: svgUri(svgColor(IconClose.data, bgColors.warning)),
            opacity: 0.80
          },
        },
      },
    },
    _error: {
      backgroundColor: bgColors.error,
       "&$_error&": { 
        color: textColors.error,
        "& $removeBtn": {
          backgroundColor: textColors.error,
          backgroundImage: svgUri(svgColor(IconClose.data, bgColors.error)),
          opacity: 1,
          "&:hover": {
            opacity: 0.7,
          },
          "&:active": {
            backgroundImage: svgUri(svgColor(IconClose.data, bgColors.error)),
            opacity: 0.85
          },
        },
      }
    },
    _medium: {
      fontSize: font.size.large,
      height: size.spacing[32],
      borderRadius: size.spacing[16],
      "& > $label": getLabelStyles(size.spacing[32], size.spacing[16]),
      "& > $icon": getIconStyles(size.spacing[24], size.spacing[16]),
      "& > $removeBtn": getRemoveBtnStyles(size.spacing[24]),
    },
    _small: {},
    _xsmall: {
      fontSize: font.size.xsmall,
      height: size.spacing[20],
      "& > $label": getLabelStyles(size.spacing[20], size.spacing[8]),
      "& > $icon": getIconStyles(size.spacing[12], size.spacing[8]),
      "& > $removeBtn": getRemoveBtnStyles(size.spacing[12]),
    },
  };
};
